import React, { useState } from 'react';
import { useDonors } from '../../contexts/DonorContext';
import DonorCard from './DonorCard';
import SplitModal from './SplitModal';

const DonorList = () => {
    const { donors } = useDonors();
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [typeFilter, setTypeFilter] = useState('all');
    const [showSplitModal, setShowSplitModal] = useState(false);

    // Count donors by status
    const pendingCount = donors.filter(d => d.status === 'pending').length;
    const processingCount = donors.filter(d => d.status === 'sending').length;
    const completedCount = donors.filter(d => d.status === 'done').length;

    // Count pending sheep and cow donors
    const pendingSheepCount = donors.filter(d => d.status === 'pending' && d.type === 'sheep').length;
    const pendingCowCount = donors.filter(d => d.status === 'pending' && d.type === 'cow').length;

    // Count cow shares (7 donors = 1 cow)
    const cowGroups = Math.floor(pendingCowCount / 7);
    const remainingCowShares = pendingCowCount % 7;

    // Filter donors based on search term and filters
    const filteredDonors = donors.filter(donor => {
        const matchesSearch =
            searchTerm === '' ||
            donor.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
            donor.lastName.toLowerCase().includes(searchTerm.toLowerCase()) ||
            donor.whatsappNumber.includes(searchTerm);

        const matchesStatus = statusFilter === 'all' || donor.status === statusFilter;
        const matchesType = typeFilter === 'all' || donor.type === typeFilter;

        return matchesSearch && matchesStatus && matchesType;
    });

    return (
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6">
                <h1 className="text-2xl font-bold">Donor Management</h1>

                <div className="mt-4 md:mt-0">
                    <button
                        className="btn btn-primary"
                        onClick={() => setShowSplitModal(true)}
                        disabled={pendingCount === 0}
                    >
                        Split Donors Between Agents
                    </button>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
                <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-yellow-400">
                    <h3 className="text-lg font-medium">Pending</h3>
                    <p className="text-3xl font-bold">{pendingCount}</p>
                </div>

                <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-blue-400">
                    <h3 className="text-lg font-medium">Processing</h3>
                    <p className="text-3xl font-bold">{processingCount}</p>
                </div>

                <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-green-400">
                    <h3 className="text-lg font-medium">Completed</h3>
                    <p className="text-3xl font-bold">{completedCount}</p>
                </div>

                <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-purple-400">
                    <h3 className="text-lg font-medium">Cow Groups</h3>
                    <p className="text-3xl font-bold">{cowGroups} <span className="text-sm font-normal">+ {remainingCowShares}/7 shares</span></p>
                </div>
            </div>

            {/* Search and filters */}
            <div className="bg-white p-4 rounded-lg shadow-sm mb-6">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Search</label>
                        <input
                            type="text"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="form-input"
                            placeholder="Search by name or number..."
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
                        <select
                            value={statusFilter}
                            onChange={(e) => setStatusFilter(e.target.value)}
                            className="form-input"
                        >
                            <option value="all">All Statuses</option>
                            <option value="pending">Pending</option>
                            <option value="sending">Processing</option>
                            <option value="done">Completed</option>
                        </select>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Type</label>
                        <select
                            value={typeFilter}
                            onChange={(e) => setTypeFilter(e.target.value)}
                            className="form-input"
                        >
                            <option value="all">All Types</option>
                            <option value="sheep">Sheep</option>
                            <option value="cow">Cow (1/7 share)</option>
                        </select>
                    </div>
                </div>
            </div>

            {/* Donor list */}
            <div>
                {filteredDonors.length > 0 ? (
                    filteredDonors.map(donor => (
                        <DonorCard
                            key={donor.id}
                            donor={donor}
                            onClick={() => { }} // Will be implemented for detailed view
                        />
                    ))
                ) : (
                    <div className="text-center py-10 bg-white rounded-lg shadow-sm">
                        <p className="text-gray-500">No donors found matching your filters.</p>
                    </div>
                )}
            </div>

            {/* Split Modal */}
            {showSplitModal && (
                <SplitModal
                    onClose={() => setShowSplitModal(false)}
                    pendingSheep={pendingSheepCount}
                    pendingCowShares={pendingCowCount}
                    cowGroups={cowGroups}
                />
            )}
        </div>
    );
};

export default DonorList;
